            // Reference always leaves balance 0; mutant may leave extra Ether
            assertTrue(address(c).balance == 0);
        } catch {
            // If withdrawAll reverts, the property is vacuously true for that path
            // but we assertTrue on the revert-respecting variant
            assertTrue(false);
        }
    }
}

