        vm.assume(actor != address(0) && actor != address(this) && actor != address(c) && actor != c.owner());
        amount = bound(amount, 1, address(c).balance + 1e18);

        vm.deal(actor, amount);
        vm.prank(actor);
        (bool depOk, ) = address(c).call{value: amount}("");
        vm.assume(depOk);

        uint256 balanceBefore = actor.balance;

        vm.prank(c.owner());
        (bool wOk, ) = address(c).call(abi.encodeWithSelector(C.withdraw.selector, amount));
        vm.assume(wOk);

        uint256 balanceAfter = actor.balance;
        assertTrue(balanceAfter == balanceBefore + amount);
    }
}
